<template>
 <div class="app-container messages">
  <div class="heading"><div><h2>消息任务</h2><p>查看后台任务的投递、处理和补偿记录，从原业务单据跟进结果。</p></div><el-button aria-label="刷新" icon="el-icon-refresh" :loading="loading" @click="load">刷新</el-button></div>
  <el-alert title="投递成功表示消息代理已接收，业务结果请看处理状态。补偿执行使用原任务入口，库存记账仍由业务流程控制。" type="info" :closable="false" show-icon />
  <el-tabs v-model="service" @tab-click="changeService"><el-tab-pane label="渠道服务 · 平台商品" name="channel"/><el-tab-pane label="订单服务 · 订单、售后与出库" name="order"/></el-tabs>
  <el-alert v-if="query.focus" :title="'当前关注：'+focusName(query.focus)+'。列表仅包含当前公司任务，队列告警统计范围为全局。'" type="warning" :closable="false"/>
  <el-form inline size="small" class="filters" @submit.native.prevent="search">
   <el-form-item label="业务类型"><el-select v-model="query.type" clearable placeholder="全部业务类型"><el-option v-for="t in types" :key="t[0]" :label="t[1]" :value="t[0]"/></el-select></el-form-item>
   <el-form-item label="处理状态"><el-select v-model="query.state" clearable placeholder="全部处理状态"><el-option v-for="(v,k) in states" :key="k" :value="k" :label="v"/></el-select></el-form-item>
   <el-form-item label="投递状态"><el-select v-model="query.publish" clearable placeholder="全部投递状态"><el-option v-for="(v,k) in publications" :key="k" :value="k" :label="v"/></el-select></el-form-item>
<el-form-item label="异常分类"><el-select v-model="query.problem" clearable placeholder="全部异常分类"><el-option v-for="(v,k) in problemNames" :key="k" :value="k" :label="v"/></el-select></el-form-item>
   <el-form-item><el-input v-model.trim="query.keyword" clearable maxlength="128" placeholder="业务单号 / 消息号 / 追踪号" style="width:300px" @keyup.enter.native="search"/></el-form-item>
   <el-form-item><el-button aria-label="查询" type="primary" icon="el-icon-search" @click="search">查询</el-button><el-button @click="reset">重置</el-button></el-form-item>
  </el-form>
  <div class="list-caption"><span>当前公司 · {{ service==='channel'?'渠道服务':'订单服务' }} · 共 {{ total }} 条</span><span>仅本页有执行中任务时每 10 秒刷新<span v-if="refreshed"> · 最近刷新 {{ refreshed }}</span></span></div>
  <el-table :data="rows" v-loading="loading" row-key="event_id" empty-text="当前条件下暂无消息任务">
   <el-table-column label="业务 / 消息" min-width="290"><template slot-scope="s"><el-link type="primary" @click="open(s.row)">{{ s.row.business_number }}</el-link><div class="muted">{{ typeName(s.row.message_type) }} · 版本 {{ s.row.business_version }}</div><div class="mono muted">{{ s.row.event_id }}</div></template></el-table-column>
   <el-table-column label="投递状态" width="170"><template slot-scope="s"><el-tag size="small" :type="pubColor(s.row.publish_state)">{{ publications[s.row.publish_state]||s.row.publish_state }}</el-tag><div class="muted">投递 {{ s.row.send_attempts }} 次</div></template></el-table-column>
   <el-table-column label="处理结果" min-width="260"><template slot-scope="s"><el-tag size="small" :type="color(s.row.process_state)">{{ states[s.row.process_state] }}</el-tag><el-tag v-if="s.row.execution_mode==='COMPENSATION'" size="mini" type="warning" class="mode">补偿执行</el-tag><div v-if="Number(s.row.has_newer)" class="muted">已有后续通知，请查看最新处理结果</div><el-tag v-if="s.row.problem && s.row.problem.code!=='NONE'" size="mini" type="warning" class="mode">{{problemNames[s.row.problem.code]}}</el-tag><div class="reason">{{ s.row.last_error || guidance(s.row) }}</div><div class="muted">{{problemAdvice(s.row)}}</div></template></el-table-column>
   <el-table-column label="进度 / 时间" min-width="205"><template slot-scope="s"><div>创建 {{ s.row.create_time }}</div><div class="muted" v-if="active(s.row)">下次处理 {{ s.row.next_process_at }}</div><div class="muted" v-else>完成 {{ s.row.completed_at || '—' }}</div><div v-if="s.row.last_publish_error && active(s.row)" class="warning">{{ s.row.last_publish_error }}</div></template></el-table-column>
   <el-table-column label="操作" width="130" fixed="right"><template slot-scope="s"><el-button type="text" @click="open(s.row)">详情 / 链路</el-button><el-button v-if="s.row.process_state==='FAILED' && !Number(s.row.has_newer)" v-hasPermi="['oms:message:retry']" type="text" @click="retry(s.row)">重试</el-button></template></el-table-column>
  </el-table>
  <pagination v-show="total>0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="load"/>
  <el-drawer title="消息任务详情" :visible.sync="visible" size="760px" append-to-body><div class="detail" v-if="detail" v-loading="detailLoading">
   <div class="detail-head"><h3>{{ detail.business_number }}</h3><el-tag :type="color(detail.process_state)">{{ Number(detail.has_newer)?'历史通知 · ':'' }}{{ states[detail.process_state] }}</el-tag><el-button v-if="latestNotice" size="small" type="success" plain @click="open(latestNotice)">查看最新通知</el-button><el-button v-if="detail.business && detail.business.path" size="small" type="primary" plain @click="business">打开业务单据</el-button><el-button size="small" @click="open(detail)">刷新详情</el-button></div>
   <el-alert v-if="latestNotice" :title="'最新通知：'+states[latestNotice.process_state]+' · '+latestNotice.event_id" :type="latestNotice.process_state==='SUCCESS'?'success':'warning'" show-icon :closable="false" class="latest-result"/>
   <el-alert :title="detail.last_error || guidance(detail)" :type="detail.process_state==='FAILED'?'error':'info'" show-icon :closable="false"/>
   <el-descriptions :column="2" border size="small" class="metadata"><el-descriptions-item label="业务类型">{{ typeName(detail.message_type) }}</el-descriptions-item><el-descriptions-item label="公司 / 服务">{{ detail.company_code }} / {{ detail.service_code }}</el-descriptions-item><el-descriptions-item label="投递状态">{{ publications[detail.publish_state] }}</el-descriptions-item><el-descriptions-item label="处理方式">{{ modeName(detail.execution_mode) }}</el-descriptions-item><el-descriptions-item v-if="active(detail)" label="下次处理时间">{{detail.next_process_at}}</el-descriptions-item><el-descriptions-item v-if="active(detail)" label="失败重试计数">{{detail.business_attempts}} 次（限流等待不计入）</el-descriptions-item><el-descriptions-item label="消息号" :span="2"><span class="mono">{{ detail.event_id }}</span></el-descriptions-item><el-descriptions-item label="追踪号" :span="2"><span class="mono">{{ detail.trace_id }}</span></el-descriptions-item></el-descriptions>
   <el-alert v-if="detail.problem" :title="problemNames[detail.problem.code]+'：'+problemAdvice(detail)" :type="detail.problem.retryable?'warning':'info'" :closable="false"/>
   <h3>同业务通知链路</h3><p class="muted">展示最近 50 条通知，最新结果置顶；原失败记录保留，后续结果请看最新通知。</p>
   <el-table :data="detail.chain || []" size="small"><el-table-column label="通知 / 版本" min-width="260"><template slot-scope="s"><el-link type="primary" @click="open(s.row)">{{s.row.event_id}}</el-link><div class="muted">版本 {{s.row.business_version}} · {{s.row.parent_event_id?'人工重试':'业务通知'}}<span v-if="s.row.event_id===detail.event_id"> · 当前查看</span></div><div v-if="s.row.parent_event_id" class="mono muted">源消息 {{s.row.parent_event_id}}</div></template></el-table-column><el-table-column label="处理结果" width="135"><template slot-scope="s"><el-tag :type="color(s.row.process_state)" size="mini">{{states[s.row.process_state]}}</el-tag><div class="muted">{{modeName(s.row.execution_mode)}}</div></template></el-table-column><el-table-column prop="create_time" label="创建时间" width="170"/></el-table>
   <h3>处理记录</h3><p class="muted">按时间倒序，最多展示最近 100 次记录。自动重试保留消息号；人工重试生成新通知，原失败记录保留。</p>
   <el-timeline v-if="detail.attempts && detail.attempts.length"><el-timeline-item v-for="(a,i) in detail.attempts" :key="i" :timestamp="a.create_time" placement="top"><strong>{{ stageName(a.stage) }} · {{ resultName(a.result) }}</strong><div>{{ a.message || '消息代理已确认接收' }}</div><div class="muted">{{ a.stage==='PUBLISH'?'消息投递':modeName(a.mode) }} · {{ a.actor }} · {{ a.duration_ms }} ms</div></el-timeline-item></el-timeline><el-empty v-else description="任务已落库，等待首次处理" :image-size="70"/>
   <el-collapse><el-collapse-item title="消息信封 · 仅业务标识" name="envelope"><pre>{{ JSON.stringify(detail.envelope,null,2) }}</pre><p class="muted">平台请求与仓库交互报文在各自交互日志查看。</p></el-collapse-item></el-collapse>
   <el-button v-if="detail.process_state==='FAILED' && !Number(detail.has_newer)" v-hasPermi="['oms:message:retry']" type="primary" size="small" @click="retry(detail)">按原业务申请重试</el-button>
  </div></el-drawer>
 </div>
</template>
<script>
import request from '@/utils/request'
import { problemNames, taskStates as states, taskQuery } from './messagePresentation'
const publications={PENDING:'待投递',SENDING:'投递中',PUBLISHED:'代理已接收',UNCERTAIN:'投递待确认',SKIPPED:'由补偿完成'}
export default {name:'MessageTasks',data(){return{service:'channel',query:{type:'',state:'',publish:'',keyword:'',problem:'',focus:'',pageNum:1,pageSize:20},states,problemNames,publications,rows:[],total:0,loading:false,visible:false,detail:null,detailLoading:false,timer:null,refreshed:'',sequence:0,alive:true}},watch:{'$route.query'(q){if(this.$route.path!=='/monitor/messages')return;if(['channel','order'].includes(q.service))this.service=q.service;this.query=taskQuery(q,this.types);this.visible=false;this.load()}},computed:{latestNotice(){const chain=this.detail && this.detail.chain;return chain && chain.length && chain[0].event_id!==this.detail.event_id?chain[0]:null},types(){return this.service==='channel'?[['PRODUCT_PULL','平台商品拉取'],['PRODUCT_BIND','平台商品自动绑定']]:[['SALES_DOCUMENT','销售出库单同步'],['ORDER_PULL','订单拉取'],['ORDER_CONVERT','平台订单转单'],['REFUND_PULL','退款拉取'],['REFUND_CONVERT','平台退款转单'],['EXCHANGE_PULL','换货拉取'],['EXCHANGE_CONVERT','平台换货转单']]}},created(){if(['channel','order'].includes(this.$route.query.service))this.service=this.$route.query.service;this.query=taskQuery(this.$route.query,this.types);this.load()},activated(){this.alive=true;if(this.refreshed)this.load(true);else this.schedule()},deactivated(){this.alive=false;clearTimeout(this.timer)},beforeDestroy(){this.alive=false;this.sequence++;clearTimeout(this.timer)},methods:{
 api(path='',method='get',data){return request({url:`/${this.service}/messages${path}`,method,...(method==='get'?{params:data}:{data})})},
 active(r){return ['PENDING','PROCESSING','WAITING'].includes(r.process_state)},typeName(t){return {PRODUCT_PULL:'平台商品拉取',PRODUCT_BIND:'平台商品自动绑定',SALES_DOCUMENT:'销售出库单同步',ORDER_PULL:'订单拉取',ORDER_CONVERT:'平台订单转单',REFUND_PULL:'退款拉取',REFUND_CONVERT:'平台退款转单',EXCHANGE_PULL:'换货拉取',EXCHANGE_CONVERT:'平台换货转单'}[t]||t},color(s){return {SUCCESS:'success',FAILED:'danger',WAITING:'warning',PROCESSING:'',PENDING:'info'}[s]},pubColor(s){return s==='PUBLISHED'?'success':s==='UNCERTAIN'?'warning':'info'},
 focusName(f){return {ACTIVE:'尚未完成任务',OVERDUE:'到期未处理任务',FAILED:'处理失败任务',PUBLISH:'待投递任务'}[f]||f},problemAdvice(r){if(Number(r.has_newer)){if(this.detail && r.event_id===this.detail.event_id && this.latestNotice)return this.latestNotice.process_state==='SUCCESS'?'最新通知已处理完成，无需重试':'请切换最新通知查看结果并处理，原通知不可重复申请';return '已有后续通知，请查看最新结果，原通知不可重复申请'}return r.problem?r.problem.advice:''},guidance(r){if(r.process_state==='SUCCESS')return r.execution_mode==='COMPENSATION'?'原任务已通过数据库补偿执行完成':'原业务任务已完成';if(Number(r.has_newer))return '已有后续通知，请查看最新消息和业务结果';if(r.process_state==='FAILED')return '请打开业务单据核对原因后申请重试';if(r.process_state==='PROCESSING')return '正在处理原业务任务';return r.publish_state==='UNCERTAIN'?'投递待确认，原任务仍保留，系统会重试或补偿':'等待消息唤醒或按断点继续处理'},modeName(m){return {MQ:'消息消费',COMPENSATION:'数据库补偿',MANUAL:'人工申请'}[m]||'待执行'},stageName(s){return {PUBLISH:'消息投递',PROCESS:'业务处理',RETRY:'人工重试'}[s]||s},resultName(s){return states[s]||publications[s]||{REQUESTED:'已申请'}[s]||s},
 schedule(){clearTimeout(this.timer);if(this.alive&&this.rows.some(this.active))this.timer=setTimeout(()=>this.load(true),10000)},async load(quiet=false){const seq=++this.sequence;if(!quiet)this.loading=true;try{const r=await this.api('','get',this.query);if(seq!==this.sequence||!this.alive)return;this.rows=r.data.rows;this.total=r.data.total;this.refreshed=new Date().toLocaleTimeString()}finally{if(seq===this.sequence){this.loading=false;this.schedule()}}},search(){this.query.pageNum=1;this.load()},reset(){this.query={type:'',state:'',publish:'',keyword:'',problem:'',focus:'',pageNum:1,pageSize:20};this.load()},changeService(){this.visible=false;this.detail=null;this.reset()},
 async open(row){this.visible=true;this.detailLoading=true;const service=this.service;try{const r=await this.api('/'+row.event_id);if(service===this.service)this.detail=r.data}finally{this.detailLoading=false}},business(){const b=this.detail.business;const {path,...query}=b;this.visible=false;this.$router.push({path,query})},async retry(row){try{const {value}=await this.$prompt('填写核对依据。系统将复用原业务处理规则并生成新通知，保留原失败记录。','申请重试',{inputType:'textarea',inputValidator:v=>!!v&&v.trim().length>0&&v.length<=255,inputErrorMessage:'请填写255字以内的核对依据'});await this.api('/'+row.event_id+'/retry','post',{reason:value.trim()});this.$message.success('已申请，请查看新消息和原业务进度');this.visible=false;this.load()}catch(e){if(e!=='cancel'&&e!=='close')console.error('Message retry unavailable')}}
}}
</script>
<style scoped>
.heading,.list-caption,.detail-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.heading h2{margin:0 0 8px;font-size:20px;color:#24374c}.heading p,.muted,.list-caption{color:#8492a6;font-size:12px;line-height:1.8}.heading{margin-bottom:18px}.filters{padding-top:12px}.list-caption{margin:2px 0 14px}.mono{font-family:Consolas,monospace;word-break:break-all}.reason{font-size:12px;line-height:1.7;margin-top:8px;color:#50627a}.mode{margin-left:6px}.warning{color:#ad790f;font-size:12px;margin-top:6px}.detail{padding:0 24px 32px}.detail-head{flex-wrap:wrap;justify-content:flex-start;margin-bottom:18px}.detail-head h3{width:100%;margin:0;word-break:break-all}.latest-result{margin-bottom:12px}.metadata{margin:20px 0 28px}.detail pre{background:#f5f7fa;padding:16px;overflow:auto;line-height:1.7}.detail ::v-deep .el-timeline{padding:10px 0 0 8px}.detail ::v-deep .el-timeline-item__content{line-height:1.8}
</style>
